===== RemotePoseStream.swift =====
   1 import Foundation
   2 import ReachyJSON
   3 
   4 /// The robot's pose over the relay, pushed on its own channel.
   5 ///
   6 /// Daemon 1.10.0 writes the state snapshot to a second data channel at about
   7 /// 30 Hz once asked, which is what this reads. It replaces polling `get_state`
   8 /// (``RemoteStateStream``) and is better in the way that matters over somebody's
   9 /// internet: nothing waits on a round trip, so a slow link loses frames instead of
  10 /// stuttering through them.
  11 ///
  12 /// **The channel is unordered and lossy by design**, which is why `seq` is read
  13 /// rather than ignored: a frame that arrives after a newer one is stale, not new,
  14 /// and drawing it would jerk the model backwards.
  15 ///
  16 /// **One reader, many subscribers.** `WebRTCDataChannel.messages()` hands its
  17 /// stream to a single consumer and finishes the previous one, so the 3D scene and
  18 /// the hearing indicator cannot each open their own — the second would silently
  19 /// take the first's frames. This reads the channel once and fans the result out,
  20 /// which is also what keeps `subscribe_pose` to one send.
  21 public final class RemotePoseStream: RobotStateStreaming, @unchecked Sendable {
  22     private let connection: RemoteRobotConnection
  23     private let channel: any RemoteDataChannel
  24     private let lock = NSLock()
  25     private var subscribers: [UUID: AsyncStream<StateStreamUpdate>.Continuation] = [:]
  26     private var reader: Task<Void, Never>?
  27 
  28     public init(connection: RemoteRobotConnection, channel: any RemoteDataChannel) {
  29         self.connection = connection
  30         self.channel = channel
  31     }
  32 
  33     deinit { reader?.cancel() }
  34 
  35     /// The options are read for nothing here, and that is the daemon's choice:
  36     /// the publisher runs at its own rate and takes no arguments. A viewer asking
  37     /// for 20 Hz gets 30 and is none the worse for it.
  38     public func updates(_: StateStreamOptions) -> AsyncStream<StateStreamUpdate> {
  39         AsyncStream { continuation in
  40             let id = UUID()
  41             lock.withLock {
  42                 subscribers[id] = continuation
  43                 startReadingLocked()
  44             }
  45             continuation.onTermination = { [weak self] _ in
  46                 self?.remove(id)
  47             }
  48         }
  49     }
  50 
  51     private func remove(_ id: UUID) {
  52         let idle: Bool = lock.withLock {
  53             subscribers.removeValue(forKey: id)
  54             return subscribers.isEmpty
  55         }
  56         // The last one out asks the robot to stop publishing. Nothing depends on
  57         // it landing — a robot still pushing to a channel nobody reads costs the
  58         // link, not correctness.
  59         guard idle else { return }
  60         let stopped = lock.withLock { () -> Task<Void, Never>? in
  61             defer { reader = nil }
  62             return reader
  63         }
  64         stopped?.cancel()
  65     }
  66 
  67     /// Called under `lock`.
  68     private func startReadingLocked() {
  69         guard reader == nil else { return }
  70         reader = Task { [connection, channel] in
  71             // Subscribed before the stream is read, not after: the daemon starts
  72             // publishing the moment it is asked, and a reader set up afterwards
  73             // would drop the first frames on the floor.
  74             try? await connection.subscribeToPose()
  75             defer { Task { try? await connection.unsubscribeFromPose() } }
  76 
  77             var diagnostics = StateStreamDiagnostics()
  78             var newest = Int.min
  79             for await text in channel.messages() {
  80                 guard !Task.isCancelled else { break }
  81                 diagnostics.receivedFrames += 1
  82                 guard let frame = try? JSONCodec.daemon.decode(
  83                     RemotePoseFrame.self,
  84                     from: Data(text.utf8)
  85                 ) else {
  86                     diagnostics.decodeFailures += 1
  87                     continue
  88                 }
  89                 guard frame.seq > newest else {
  90                     // Out of order, which this channel is allowed to be.
  91                     diagnostics.unsupportedFrames += 1
  92                     continue
  93                 }
  94                 newest = frame.seq
  95                 diagnostics.decodedFrames += 1
  96                 self.broadcast(StateStreamUpdate(
  97                     frame: frame.state.frame,
  98                     diagnostics: diagnostics
  99                 ))
 100             }
 101             self.finishAll()
 102         }
 103     }
 104 
 105     private func broadcast(_ update: StateStreamUpdate) {
 106         for continuation in lock.withLock({ subscribers.values }) {
 107             continuation.yield(update)
 108         }
 109     }
 110 
 111     private func finishAll() {
 112         for continuation in lock.withLock({ subscribers.values }) {
 113             continuation.finish()
 114         }
 115     }
 116 }

